// Repaso narrado, independiente de las calificaciones del profesor IA.
const guided={request:0,lesson:null,index:0,token:0,playing:false,paused:false,chunk:0,chunks:[],utterance:null,rate:1,voice:'',continuous:true,mode:'guided'};
function guidedTopics(){return currentSubject==='termicas'?[...thermalLearningTopics]:coursePractice[currentSubject].topics}
function guidedStore(){saved.guided||={unit:0,positions:{},completed:[]};saved.guided.positions||={};saved.guided.completed||=[];return saved.guided}
function guidedSave(){const state=guidedStore();state.unit=guided.lesson?.unit??state.unit;state.positions[state.unit]=guided.index;persist()}
window.cleanupGuided=()=>{guided.request++;guided.token++;guided.playing=false;guided.paused=false;guided.utterance=null;window.speechSynthesis?.cancel()};
function guidedStop(){guided.token++;guided.playing=false;guided.paused=false;guided.chunk=0;guided.utterance=null;window.speechSynthesis?.cancel();guidedAudioUI()}
function guidedAudioUI(message){const status=document.querySelector('#guided-audio-status');if(status)status.textContent=message||(guided.paused?'Lectura en pausa.':guided.playing?'Leyendo la sección '+(guided.index+1)+'…':'Listo para escuchar.');const play=document.querySelector('#guided-play');if(play)play.textContent=guided.paused?'▶ Reanudar':guided.playing?'Ⅱ Pausar':'▶ Escuchar al profesor';document.querySelectorAll('[data-lesson-section]').forEach((b,i)=>{b.classList.toggle('current',i===guided.index);if(i===guided.index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}
function guidedText(section){const visual=window.guidedThermalText?.(section);if(visual)return visual;return [section.title,...section.paragraphs,...(section.flow?[section.flow.join('. Después, ')+'.']:[]),...(section.legend||[]),...(section.model?['Una posible apertura para tu respuesta. '+section.model]:[]),...(section.list?['Al terminar, comprobá que podés explicar lo siguiente.',...section.list]:[]),...(section.pitfall?['Error que conviene evitar. '+section.pitfall]:[])].join('\n')}
function splitGuidedSpeech(text){return text.match(/[^.!?\n]+[.!?]?/g)?.flatMap(s=>{const words=s.trim().split(/\s+/),out=[];for(let i=0;i<words.length;i+=35)out.push(words.slice(i,i+35).join(' '));return out}).filter(Boolean)||[]}
function guidedSpeak(restart=false){const engine=window.speechSynthesis;if(!engine||typeof SpeechSynthesisUtterance==='undefined'){guidedAudioUI('Tu navegador no ofrece lectura en voz alta. Podés seguir todo el repaso por texto.');return}if(guided.paused&&!restart){guided.paused=false;engine.resume();guidedAudioUI();return}if(guided.playing&&!restart){guided.paused=true;engine.pause();guidedAudioUI();return}guidedStop();guided.chunks=splitGuidedSpeech(guidedText(guided.lesson.sections[guided.index]));guided.chunk=0;guided.playing=true;const token=guided.token;guidedReadChunk(token)}
function guidedReadChunk(token){if(token!==guided.token||!guided.playing||location.hash!=='#oral'||guided.mode!=='guided')return;if(guided.chunk>=guided.chunks.length){guided.playing=false;if(guided.continuous&&window.guidedAdvanceVisual?.()){guidedSpeak(true);return}if(guided.continuous&&guided.index<guided.lesson.sections.length-1){guided.index++;guidedSave();guidedSection();guidedSpeak(true)}else guidedAudioUI('Lectura terminada. Repasá la lista y marcá el tema cuando lo hayas comprendido.');return}const u=new SpeechSynthesisUtterance(guided.chunks[guided.chunk]);u.lang='es-AR';u.rate=guided.rate;u.onend=()=>{if(token!==guided.token)return;guided.chunk++;guidedReadChunk(token)};u.onerror=e=>{if(token!==guided.token)return;guided.playing=false;guided.paused=false;guidedAudioUI(e.error==='not-allowed'?'El navegador necesita que pulses Escuchar para habilitar la voz.':'No se pudo continuar la voz. Pulsá Repetir sección o seguí con el texto.')};guided.utterance=u;if(window.finalesSpeech)window.finalesSpeech.speak(u,{preferred:guided.voice,isCurrent:()=>token===guided.token&&guided.playing,onUtterance:next=>{guided.utterance=next}});else speechSynthesis.speak(u);guidedAudioUI()}
function guidedVoiceOptions(){const select=document.querySelector('#guided-voice');if(!select)return;const voices=window.speechSynthesis?.getVoices().filter(v=>v.lang.startsWith('es'))||[];select.innerHTML='<option value="">Automática · Argentina / Google / sistema</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}</option>`).join('');select.value=guided.voice}
window.speechSynthesis?.addEventListener('voiceschanged',guidedVoiceOptions);
window.addEventListener('scroll',()=>{const player=document.querySelector('.guided-player');if(player)player.classList.toggle('compact',innerWidth>1000&&player.getBoundingClientRect().top<=12)},{passive:true});
function guidedFlow(items){return `<ol class="guided-flow" aria-label="Recorrido conceptual">${items.map((text,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(text)}</strong>${i<items.length-1?'<b aria-hidden="true">→</b>':''}</li>`).join('')}</ol><p class="source">Esquema conceptual propio · las flechas muestran relaciones para estudiar.</p>`}
function guidedSection(){const lesson=guided.lesson,s=lesson.sections[guided.index],target=document.querySelector('#guided-content');if(!target)return;target.innerHTML=`<p class="eyebrow">${esc(s.label)} · SECCIÓN ${guided.index+1} DE ${lesson.sections.length}</p><h2 tabindex="-1" id="guided-section-title">${esc(s.title)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${window.guidedThermalHTML?.(s)||''}${s.flow?guidedFlow(s.flow):''}${s.image?`<figure class="guided-figure"><a href="${esc(s.image)}" target="_blank" rel="noopener"><img src="${esc(s.image)}" alt="${esc(s.title)}: esquema numerado; nombres y funciones en la leyenda inferior"></a><figcaption>Ampliá el esquema para seguir cada referencia.</figcaption></figure><ol class="guided-legend">${s.legend.map(p=>`<li>${esc(p.replace(/^\d+\.\s*/,''))}</li>`).join('')}</ol>`:''}${s.model?`<div class="guided-model"><span class="eyebrow">UNA POSIBLE APERTURA DEL ORAL</span><p>${esc(s.model)}</p><small>Completala con el mapa, el ejemplo y los detalles de esta lección. No hace falta memorizarla literalmente.</small></div>`:''}${s.list?`<h3>Antes de pasar al siguiente tema</h3><ul class="guided-checklist">${s.list.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}${s.pitfall?`<div class="guided-pitfall"><strong>Evitá esta confusión</strong><p>${esc(s.pitfall)}</p></div>`:''}${s.sources?.length?`<details class="guided-sources"><summary>Consultar las referencias de este apartado</summary>${s.sources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a>`).join('')}</details>`:''}`;document.querySelector('#guided-prev').disabled=guided.index===0;document.querySelector('#guided-next').disabled=guided.index===lesson.sections.length-1;document.querySelector('#guided-count').textContent=`${guided.index+1} / ${lesson.sections.length}`;document.querySelector('#guided-complete').hidden=guided.index!==lesson.sections.length-1;document.querySelector('#guided-section-progress').value=guided.index+1;guidedAudioUI();window.bindGuidedThermalSteps?.()}
function guidedGoSection(index,{focus=false,listen=false}={}){guidedStop();guided.index=index;guidedSave();guidedSection();if(focus)document.querySelector('#guided-section-title')?.focus();if(listen)guidedSpeak(true)}
async function renderGuidedReview(unit,options={}){window.cleanupGuided();guided.mode='guided';const subject=currentSubject,state=guidedStore(),topics=guidedTopics();if(unit===undefined&&Number.isInteger(window.subjectReviewTopic)&&window.subjectReviewTopic>=0){unit=window.subjectReviewTopic;window.subjectReviewTopic=undefined}if(!Number.isInteger(unit)||unit<0||unit>=topics.length)unit=Number.isInteger(state.unit)&&state.unit<topics.length?state.unit:0;const request=guided.request;
 document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#oral'));app.innerHTML=head('REPASO GUIADO · '+navalSubjects[subject].name,'Primero comprendé. Después explicalo.','Un recorrido en orden, con la voz del profesor, mapas y ejemplos para preparar el oral.')+`<div class="guided-loading" role="status">Preparando la explicación…</div>`;
 try{const lesson=await accountAPI('/api/study',{action:'lesson',subject,unit});if(request!==guided.request||subject!==currentSubject||location.hash!=='#oral')return;guided.lesson=lesson;guided.index=Math.max(0,Math.min(state.positions[unit]||0,lesson.sections.length-1));if(options.sectionId){const target=lesson.sections.findIndex(s=>s.id===options.sectionId);if(target>=0)guided.index=target}guidedSave();
 app.innerHTML=head('REPASO GUIADO · '+navalSubjects[subject].name,'Primero comprendé. Después explicalo.','Escuchá, seguí el mapa y practicá la explicación. El recorrido respeta el orden de los temas.')+`${window.guidedThermalNav?.(lesson)||''}<div class="guided-mode"><strong>Aprender con el profesor</strong><button id="guided-questions" class="secondary">Practicar con preguntas →</button></div><div class="guided-layout"><section class="guided-outline" aria-label="Recorrido de la materia"><label for="guided-topic">Tema de estudio</label><select id="guided-topic">${topics.map((name,i)=>`<option value="${i}">${i+1}. ${esc(name)}${state.completed.includes(i)?' · repasado':''}</option>`).join('')}</select><p>${state.completed.length} de ${topics.length} temas marcados como repasados</p><progress max="${topics.length}" value="${state.completed.length}" aria-label="Temas repasados"></progress><p class="source">Avance de lectura en este navegador, separado por materia y cuenta. Las notas del examen se guardan en Mi progreso.</p><h3>En esta lección</h3><ol class="guided-section-list">${lesson.sections.map((s,i)=>`<li><button data-lesson-section="${i}">${esc(s.title)}</button></li>`).join('')}</ol><p class="source">Lectura orientativa: ${lesson.minutes} min · ${lesson.questionCount} conceptos de examen.</p>${lesson.basis==='materiales'?'<p class="source">Orden organizado según los apuntes disponibles; no equivale a un programa oficial completo.</p>':''}</section><div class="guided-main"><section class="guided-player" aria-label="Voz del profesor"><div class="guided-player-heading"><span class="eyebrow">ESCUCHAR Y SEGUIR</span><span id="guided-count"></span></div><div class="actions"><button id="guided-play">▶ Escuchar al profesor</button><button class="secondary" id="guided-repeat">↻ Repetir sección</button><button class="secondary" id="guided-stop">■ Detener</button></div><div class="guided-voice-settings"><label>Velocidad<select id="guided-rate"><option value="0.8">Pausada · 0,8×</option><option value="1">Normal · 1×</option><option value="1.2">Ágil · 1,2×</option></select></label><label>Voz del profesor<select id="guided-voice" aria-label="Voz del profesor"></select></label></div><label class="guided-continuous"><input id="guided-continuous" type="checkbox" ${guided.continuous?'checked':''}> Continuar automáticamente por las secciones de este tema</label><p id="guided-audio-status" role="status" aria-live="polite"></p><progress id="guided-section-progress" max="${lesson.sections.length}" aria-label="Sección actual de la lección"></progress><small>La lectura usa las voces de tu navegador. Empieza cuando pulsás Escuchar.</small></section><article class="guided-content" id="guided-content" aria-label="Explicación del profesor"></article><div class="guided-navigation"><button class="secondary" id="guided-prev">← Sección anterior</button><button id="guided-next">Siguiente sección →</button></div><section id="guided-complete" class="guided-completion"><h3>¿Podés explicarlo sin mirar?</h3><p>Ensayá la lista de conceptos antes de marcarlo. Leer o escuchar no cambia tu nota del examen.</p><div class="actions"><button id="guided-mark">${state.completed.includes(unit)?'✓ Tema repasado · desmarcar':'Marcar tema como repasado'}</button><button class="secondary" id="guided-next-topic" ${unit===topics.length-1?'disabled':''}>Siguiente tema →</button><button class="secondary" id="guided-exam">Responder al profesor IA</button></div></section><details class="guided-sources"><summary>Materiales y alcance del repaso</summary><p>${esc(lesson.notice)}</p>${lesson.sources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a>`).join('')}</details></div></div>`;
 document.querySelector('#guided-topic').value=unit;document.querySelector('#guided-topic').onchange=e=>renderGuidedReview(+e.target.value);document.querySelectorAll('[data-lesson-section]').forEach(b=>b.onclick=()=>guidedGoSection(+b.dataset.lessonSection,{focus:true}));document.querySelector('#guided-prev').onclick=()=>guidedGoSection(guided.index-1,{focus:true});document.querySelector('#guided-next').onclick=()=>guidedGoSection(guided.index+1,{focus:true});document.querySelector('#guided-play').onclick=()=>guidedSpeak();document.querySelector('#guided-repeat').onclick=()=>guidedSpeak(true);document.querySelector('#guided-stop').onclick=guidedStop;document.querySelector('#guided-rate').value=guided.rate;document.querySelector('#guided-rate').onchange=e=>{const active=guided.playing;guided.rate=+e.target.value;if(active)guidedSpeak(true)};document.querySelector('#guided-voice').onchange=e=>{const active=guided.playing;guided.voice=e.target.value;if(active)guidedSpeak(true)};document.querySelector('#guided-continuous').onchange=e=>guided.continuous=e.target.checked;document.querySelector('#guided-questions').onclick=()=>renderGuidedQuestions(0);document.querySelector('#guided-mark').onclick=()=>{state.completed=state.completed.includes(unit)?state.completed.filter(x=>x!==unit):[...state.completed,unit];persist();renderGuidedReview(unit)};document.querySelector('#guided-next-topic').onclick=()=>renderGuidedReview(unit+1);document.querySelector('#guided-exam').onclick=()=>{exam.unit=unit;exam.scope=unit>=10?'completo':exam.scope;location.hash='profesor'};guidedVoiceOptions();guidedSection();window.bindGuidedThermalNav?.();if(options.sectionId)document.querySelector('#guided-section-title')?.focus();
 }catch(e){if(request!==guided.request)return;app.innerHTML=head('REPASO GUIADO','No se pudo cargar este tema.',esc(e.message))+'<button id="guided-retry">Volver a intentar</button>';document.querySelector('#guided-retry').onclick=()=>renderGuidedReview(unit)}}

function renderGuidedQuestions(position=0){window.cleanupGuided();guided.mode='questions';const lesson=guided.lesson,subject=currentSubject,card=lesson.practice[position];app.innerHTML=head('APLICAR LO ESTUDIADO · '+lesson.topic,'Ahora explicalo vos.','Preguntas del mismo tema, en orden. Compará la referencia después de ensayar tu respuesta.')+`<div class="guided-mode"><button id="guided-back" class="secondary">← Volver a la explicación guiada</button><span>${position+1} / ${lesson.practice.length}</span></div><section class="oral-card"><h2>${esc(card.question)}</h2><textarea id="guided-practice-text" aria-label="Tu respuesta de repaso" placeholder="Definición, relaciones, explicación y ejemplo…">${esc(saved.answers['guided-'+card.id]||'')}</textarea><div class="actions"><button id="guided-practice-reveal" class="secondary">Comparar con la referencia</button><button id="guided-practice-next" ${position===lesson.practice.length-1?'disabled':''}>Siguiente pregunta →</button><button class="secondary" id="guided-practice-exam">Evaluar con el profesor IA</button></div><div id="guided-practice-answer" class="answer" hidden></div><p class="source">Este ensayo no asigna una nota. El profesor IA evalúa tus respuestas y guarda los resultados del examen.</p></section>`;document.querySelector('#guided-back').onclick=()=>renderGuidedReview(lesson.unit);document.querySelector('#guided-practice-text').oninput=e=>{saved.answers['guided-'+card.id]=e.target.value;persist()};document.querySelector('#guided-practice-next').onclick=()=>renderGuidedQuestions(position+1);document.querySelector('#guided-practice-exam').onclick=()=>{exam.unit=lesson.unit;if(lesson.unit>=10)exam.scope='completo';location.hash='profesor'};document.querySelector('#guided-practice-reveal').onclick=async e=>{const button=e.currentTarget,target=document.querySelector('#guided-practice-answer'),request=guided.request;button.disabled=true;target.hidden=false;target.textContent='Cargando referencia…';try{const result=await accountAPI('/api/study',{subject,id:card.id});if(request!==guided.request)return;target.innerHTML='<p>'+esc(result.answer)+'</p>'+(result.sources||[]).map(r=>`<a target="_blank" rel="noopener" href="${esc(examSourceURL(r))}">${esc(r.title)} ↗</a>`).join('<br>')}catch(error){if(request===guided.request)target.textContent=error.message}finally{button.disabled=false}}}
if(location.hash==='#oral')render();
